// --- Attach the per-session API token to our own /api/ calls ------------------
// The token lives in the readable `ctok` cookie (set by the server on each page
// load). Echoing it back in the x-api-token header lets the server tell a real
// visitor apart from a third party embedding or scraping the API. Only touches
// same-origin /api/ requests; everything else passes through untouched, and any
// error here silently falls back to the native fetch so the site never breaks.
(function () {
  if (window.__apiFetchPatched || typeof window.fetch !== 'function') return;
  window.__apiFetchPatched = true;
  var nativeFetch = window.fetch.bind(window);
  function readToken() {
    var m = document.cookie.match(/(?:^|;\s*)ctok=([^;]+)/);
    return m ? decodeURIComponent(m[1]) : '';
  }
  window.fetch = function (input, init) {
    try {
      var url = typeof input === 'string' ? input : (input && input.url) || '';
      if (url.indexOf('/api/') === 0 || url.indexOf(location.origin + '/api/') === 0) {
        init = init || {};
        var headers = new Headers(init.headers || {});
        var tok = readToken();
        if (tok) headers.set('x-api-token', tok);
        init.headers = headers;
        if (!init.credentials) init.credentials = 'same-origin';
      }
    } catch (e) { /* never break fetch */ }
    return nativeFetch(input, init);
  };
})();

// ---- Icon system (Lucide, MIT). Replaces emojis with clean inline SVG. ----
function iconSvg(name, cls) {
  const inner = window.LUCIDE && window.LUCIDE[name];
  if (!inner) return '';
  return '<svg class="icon ' + (cls || '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
    'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + inner + '</svg>';
}
window.icon = iconSvg;

// Replace every <span data-icon="name"></span> (or any element) with its SVG.
// Safe to call repeatedly and on dynamically-inserted subtrees (app.js does).
window.applyIcons = function (root) {
  const scope = root || document;
  scope.querySelectorAll('[data-icon]').forEach(function (el) {
    if (el.__iconDone) return;
    const svg = iconSvg(el.getAttribute('data-icon'), el.getAttribute('data-icon-class') || '');
    if (svg) {
      el.innerHTML = svg;
      el.__iconDone = true;
    }
  });
};

// Shared on every page (unlike app.js, which only loads on the search pages):
// icon injection + theme toggle persistence + the header's live record count.
// Peru map path, fetched once and reused by every result panel on the page.
let peruPathPromise = null;
function getPeruPath() {
  if (!peruPathPromise) {
    peruPathPromise = fetch('/peru-map.svg')
      .then((r) => r.text())
      .then((t) => { const m = t.match(/<path d="([\s\S]*?)"/); return m ? m[1] : ''; })
      .catch(() => '');
  }
  return peruPathPromise;
}
window.getPeruPath = getPeruPath;

window.buildPeruMap = function (pathD, point) {
  if (!pathD) return '';
  const marker = point
    ? `<circle class="lima-dot" cx="${point.x}" cy="${point.y}" r="20"/>` +
      `<text class="lima-label" x="${point.x + 28}" y="${point.y + 20}">${point.name}</text>`
    : '';
  return `<svg viewBox="0 0 1024 1024" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Mapa del Perú">
    <g transform="translate(0,1024) scale(0.1,-0.1)" fill="currentColor"><path d="${pathD}"/></g>${marker}</svg>`;
};

/**
 * Auto-mounts anything marked with [data-component]. This is what makes
 * dropping a component onto a new page a one-liner:
 *   <div data-component="search-bar" data-mode="nombre"></div>
 */
function mountComponents() {
  document.querySelectorAll('[data-component]').forEach(function (el) {
    if (el.__mounted || !window.CRP) return;
    const name = el.getAttribute('data-component');
    if (name === 'search-bar') {
      el.innerHTML = window.CRP.searchBar({ mode: el.dataset.mode, cta: el.dataset.cta, tabs: el.dataset.tabs });
      el.__mounted = true;
    }
  });
}
window.mountComponents = mountComponents;

document.addEventListener('DOMContentLoaded', function () {
  mountComponents();
  window.applyIcons(document);

  const themeToggle = document.getElementById('themeToggle');
  const body = document.body;

  function applyTheme(isLight) {
    body.classList.toggle('light-theme', isLight);
    if (themeToggle) themeToggle.innerHTML = iconSvg(isLight ? 'moon' : 'sun');
  }

  const saved = localStorage.getItem('crp_theme');
  let isLight = body.classList.contains('light-theme');
  if (saved === 'dark') isLight = false;
  else if (saved === 'light') isLight = true;
  applyTheme(isLight);

  if (themeToggle) {
    themeToggle.addEventListener('click', function () {
      const nowLight = !body.classList.contains('light-theme');
      applyTheme(nowLight);
      localStorage.setItem('crp_theme', nowLight ? 'light' : 'dark');
    });
  }

  const statEl = document.getElementById('statCount');
  if (statEl) {
    fetch('/api/stats')
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (d && d.success && d.count) statEl.textContent = d.count.toLocaleString('es-PE');
      })
      .catch(function () {});
  }

  // Table-of-contents scroll-spy: highlight the section currently in view.
  const toc = document.getElementById('artToc');
  if (toc) {
    const links = Array.prototype.slice.call(toc.querySelectorAll('a'));
    const map = {};
    links.forEach(function (a) { map[a.getAttribute('href').slice(1)] = a; });
    // Keep the active link visible inside the (now scrollable) TOC without
    // moving the page: nudge only the TOC's own scrollTop by the overflow.
    function ensureVisible(a) {
      var cr = toc.getBoundingClientRect();
      var ar = a.getBoundingClientRect();
      if (ar.top < cr.top + 8) toc.scrollTop -= (cr.top + 8 - ar.top);
      else if (ar.bottom > cr.bottom - 8) toc.scrollTop += (ar.bottom - (cr.bottom - 8));
    }
    const obs = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) {
          links.forEach(function (a) { a.classList.remove('active'); });
          if (map[e.target.id]) { map[e.target.id].classList.add('active'); ensureVisible(map[e.target.id]); }
        }
      });
    }, { rootMargin: '-80px 0px -70% 0px' });
    document.querySelectorAll('.art-section').forEach(function (s) { obs.observe(s); });

    // Reading-progress bar at the top of the TOC: fills as the article is read.
    //
    // The markup now ships in the HTML instead of being created here. Injecting
    // two elements after first paint pushed the whole table of contents down and
    // was measured as a 0.328 layout shift on mobile (CLS 0.339 overall, the
    // single biggest drag on the performance score). Reserving the space in the
    // document costs nothing and makes the shift impossible.
    var content = document.querySelector('.art-body') || document.querySelector('.art-main');
    var bar = toc.querySelector('.art-toc-progress');
    var label = toc.querySelector('.art-toc-progress-label');
    if (content && bar && label) {
      var fill = bar.querySelector('.art-toc-progress-fill');
      var pctEl = label.querySelector('.art-toc-pct');
      var ticking = false;
      function updateProgress() {
        ticking = false;
        var r = content.getBoundingClientRect();
        var start = r.top + window.scrollY;
        var readable = r.height - window.innerHeight;
        var pct = readable > 0 ? (window.scrollY - start) / readable : (window.scrollY >= start ? 1 : 0);
        pct = Math.max(0, Math.min(1, pct));
        fill.style.width = (pct * 100).toFixed(1) + '%';
        pctEl.textContent = Math.round(pct * 100) + '%';
      }
      window.addEventListener('scroll', function () { if (!ticking) { ticking = true; requestAnimationFrame(updateProgress); } }, { passive: true });
      window.addEventListener('resize', updateProgress);
      updateProgress();
    }
  }

  // Right sidebar "Consulta rápida" fallback for pages WITHOUT the search bar
  // (calculadora, tipo de cambio, verificación múltiple — they don't load app.js).
  // On search pages app.js owns this, so we only wire it when app.js is absent.
  if (typeof executeSearch === 'undefined') {
    // paint recent-search history from localStorage
    var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); };
    var hist = [];
    try { hist = JSON.parse(localStorage.getItem('crp_history')) || []; } catch (e) { hist = []; }
    var histBox = document.getElementById('artHistoryList');
    if (histBox && hist.length) {
      histBox.innerHTML = '';
      hist.forEach(function (h) {
        var a = document.createElement('a');
        a.className = 'aside-hist';
        a.href = '/ruc/' + encodeURIComponent(h.ruc);
        a.innerHTML = '<strong>' + esc(h.ruc) + '</strong><span>' + esc(h.razonSocial) + '</span>';
        histBox.appendChild(a);
      });
    }
    // quick-search: navigate to the server-rendered result page
    var aq = document.getElementById('asideQuickForm');
    if (aq) {
      aq.addEventListener('submit', function (e) {
        e.preventDefault();
        var box = document.getElementById('asideQuickInput');
        var v = (box.value || '').replace(/\D/g, '');
        if (v.length !== 11) {
          box.classList.remove('shake');
          void box.offsetWidth;
          box.classList.add('shake');
          return;
        }
        window.location.href = '/ruc/' + encodeURIComponent(v);
      });
    }
    var topBtn = document.getElementById('asideTop');
    if (topBtn) topBtn.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); });
  }
});

// Result panel: functional tabs + print. Event delegation so it works both on
// the SSR /ruc/ page and on dynamically-rendered homepage search results.
document.addEventListener('click', function (e) {
  if (!e.target.closest) return;
  var tab = e.target.closest('.rp-tab');
  if (tab) {
    var wrap = tab.closest('.rp-profile');
    if (!wrap) return;
    var key = tab.getAttribute('data-tab');
    wrap.querySelectorAll('.rp-tab').forEach(function (t) { t.classList.toggle('active', t === tab); });
    wrap.querySelectorAll('.rp-panel').forEach(function (pn) { pn.classList.toggle('active', pn.getAttribute('data-panel') === key); });
    return;
  }
  var printBtn = e.target.closest('[data-action="print"]');
  if (printBtn) {
    e.preventDefault();
    // A client-rendered result routes to the clean /ruc/ page (auto-prints
    // there); the /ruc/ page itself prints in place.
    var pruc = printBtn.getAttribute('data-print-ruc');
    if (pruc && !/^\/ruc\//.test(location.pathname)) location.href = '/ruc/' + pruc + '?print=1';
    else window.print();
  }
});

// Auto-open the print dialog when the clean ficha page is reached with ?print=1.
(function () {
  if (/^\/ruc\//.test(location.pathname) && /[?&]print=1/.test(location.search)) {
    window.addEventListener('load', function () { setTimeout(function () { window.print(); }, 500); });
  }
})();

// --- Image lightbox: click/Enter/Space any .art-figure image to zoom it into
// an accessible, blurred-backdrop dialog. Keyboard + screen-reader friendly:
// role=dialog/aria-modal, focus moves to the close button and returns to the
// trigger, Esc and backdrop close, body scroll locked while open.
(function () {
  function initLightbox() {
    var figs = document.querySelectorAll('.art-figure img');
    if (!figs.length || document.querySelector('.lightbox')) return;

    var lb = document.createElement('div');
    lb.className = 'lightbox';
    lb.setAttribute('role', 'dialog');
    lb.setAttribute('aria-modal', 'true');
    lb.setAttribute('aria-label', 'Imagen ampliada');
    lb.hidden = true;
    lb.innerHTML =
      '<div class="lightbox-backdrop" data-close></div>' +
      '<div class="lightbox-content">' +
        '<button type="button" class="lightbox-close" aria-label="Cerrar imagen (tecla Escape)">×</button>' +
        '<img class="lightbox-img" alt="">' +
        '<p class="lightbox-cap"></p>' +
      '</div>';
    document.body.appendChild(lb);

    var lbImg = lb.querySelector('.lightbox-img');
    var lbCap = lb.querySelector('.lightbox-cap');
    var closeBtn = lb.querySelector('.lightbox-close');
    var lastFocus = null;

    function onKey(e) {
      if (e.key === 'Escape') { close(); }
      else if (e.key === 'Tab') { e.preventDefault(); closeBtn.focus(); } // only focusable node
    }
    function open(img) {
      lastFocus = img;
      lbImg.src = img.currentSrc || img.src;
      lbImg.alt = img.alt || '';
      lbCap.textContent = img.alt || '';
      lb.hidden = false;
      document.body.classList.add('lb-open');
      closeBtn.focus();
      document.addEventListener('keydown', onKey);
    }
    function close() {
      lb.hidden = true;
      document.body.classList.remove('lb-open');
      document.removeEventListener('keydown', onKey);
      if (lastFocus && lastFocus.focus) lastFocus.focus();
    }
    closeBtn.addEventListener('click', close);
    lb.addEventListener('click', function (e) {
      if (e.target.hasAttribute('data-close')) close();
    });

    figs.forEach(function (img) {
      var fig = img.closest('.art-figure');
      if (fig) fig.classList.add('zoomable');
      img.setAttribute('tabindex', '0');
      img.setAttribute('role', 'button');
      if (!img.getAttribute('aria-label')) {
        img.setAttribute('aria-label', 'Ampliar imagen: ' + (img.alt || '').slice(0, 90));
      }
      img.addEventListener('click', function () { open(img); });
      img.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open(img); }
      });
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initLightbox);
  else initLightbox();
})();

// --- Mobile hamburger menu: build a slide-in drawer from the existing
// .tab-nav so the menu stays in sync with the real navigation. Accessible:
// aria-expanded on the toggle, role=dialog, Esc + overlay + link click close,
// focus moves to the close button and back, body scroll locked while open.
(function () {
  function initDrawer() {
    var toggle = document.getElementById('menuToggle');
    var tabNav = document.querySelector('.tab-nav-container');
    if (!toggle || !tabNav || document.querySelector('.drawer-overlay')) return;

    var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); };
    var items = '';
    Array.prototype.forEach.call(tabNav.children, function (child) {
      if (child.tagName === 'A') {
        items += '<a href="' + esc(child.getAttribute('href')) + '"' + (child.classList.contains('active') ? ' class="active"' : '') + '>' + esc(child.textContent.trim()) + '</a>';
      } else if (child.classList && child.classList.contains('nav-group')) {
        var trig = child.querySelector('.nav-trigger');
        items += '<p class="drawer-group">' + esc(trig ? trig.textContent.trim() : '') + '</p>';
        child.querySelectorAll('.nav-menu a').forEach(function (a) {
          items += '<a href="' + esc(a.getAttribute('href')) + '"' + (a.classList.contains('active') ? ' class="active"' : '') + '>' + esc(a.textContent.trim()) + '</a>';
        });
      }
    });

    var overlay = document.createElement('div');
    overlay.className = 'drawer-overlay';
    overlay.hidden = true;
    overlay.innerHTML =
      '<div class="mobile-drawer" role="dialog" aria-modal="true" aria-label="Menú de navegación">' +
        '<div class="drawer-head"><span class="drawer-title">Menú</span>' +
        '<button type="button" class="drawer-close" aria-label="Cerrar menú">×</button></div>' +
        '<nav class="drawer-nav">' + items + '</nav>' +
      '</div>';
    document.body.appendChild(overlay);

    var closeBtn = overlay.querySelector('.drawer-close');
    function onKey(e) { if (e.key === 'Escape') close(); }
    function open() {
      overlay.hidden = false;
      document.body.classList.add('drawer-open');
      toggle.setAttribute('aria-expanded', 'true');
      closeBtn.focus();
      document.addEventListener('keydown', onKey);
    }
    function close() {
      overlay.hidden = true;
      document.body.classList.remove('drawer-open');
      toggle.setAttribute('aria-expanded', 'false');
      document.removeEventListener('keydown', onKey);
      toggle.focus();
    }
    toggle.addEventListener('click', function () { overlay.hidden ? open() : close(); });
    closeBtn.addEventListener('click', close);
    overlay.addEventListener('click', function (e) { if (e.target === overlay) close(); });
    overlay.querySelectorAll('.drawer-nav a').forEach(function (a) { a.addEventListener('click', close); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initDrawer);
  else initDrawer();
})();

// --- Bulk file picker: reflect the chosen file name in the styled drop zone
// (homepage "Búsqueda Masiva" widget). Delegated so it works regardless of
// when app.js mounts the search component.
document.addEventListener('change', function (e) {
  var input = e.target;
  if (input && input.id === 'bulkFile') {
    var out = document.getElementById('bulkFileName');
    if (out) out.textContent = (input.files && input.files[0]) ? input.files[0].name : '';
  }
});

// --- Byline functionality: reading-time estimate + copy-link share button.
// (Print is handled by the existing [data-action="print"] delegation.)
(function () {
  function initByline() {
    var rt = document.querySelector('.js-readtime');
    var body = document.querySelector('.art-body');
    if (rt && body) {
      var words = (body.innerText || body.textContent || '').trim().split(/\s+/).filter(Boolean).length;
      rt.textContent = Math.max(1, Math.round(words / 200));
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initByline);
  else initByline();
  document.addEventListener('click', function (e) {
    var btn = e.target.closest('.js-share');
    if (!btn) return;
    var done = function () { btn.classList.add('copied'); setTimeout(function () { btn.classList.remove('copied'); }, 1600); };
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(location.href).then(done, done);
      else done();
    } catch (err) { done(); }
  });
})();
